import { Injectable } from '@nestjs/common';
import { spawn } from 'node:child_process';
import * as path from 'node:path';
import { mkdir } from 'node:fs/promises';
import { PinoLogger } from 'nestjs-pino';

/**
 * Packages transcoded video and audio files into adaptive streaming formats
 * using Shaka Packager.
 *
 * The service takes the output generated by FfmpegService and packages
 * the available video variants together with the shared audio track.
 *
 * Supported resolutions:
 *
 * - 144p  -> 256x144
 * - 360p  -> 640x360
 * - 480p  -> 854x480
 * - 720p  -> 1280x720
 * - 1080p -> 1920x1080
 *
 * The worker selects the maximum resolution based on the original video's
 * height and calls the corresponding method:
 *
 * - toMax144()
 * - toMax360()
 * - toMax480()
 * - toMax720()
 * - toMax1080()
 *
 * Shaka Packager does not re-encode the media. It packages the already
 * transcoded MP4 files into streaming segments and generates the required
 * manifests.
 *
 * Output structure:
 *
 * packed/
 * ├── audio/
 * │   └── ...
 * ├── video/
 * │   ├── 144/
 * │   │   └── ...
 * │   ├── 360/
 * │   │   └── ...
 * │   ├── 480/
 * │   │   └── ...
 * │   ├── 720/
 * │   │   └── ...
 * │   └── 1080/
 * │       └── ...
 * ├── dash/
 * │   └── manifest.mpd
 * └── hls/
 *     └── master.m3u8
 *
 * CLI equivalent:
 *
 * packager \
 *   "in=.temp/[videoId]/transcoded/video/144/video.mp4,stream=video,output=.temp/[videoId]/packed/video/144/video.mp4" \
 *   "in=.temp/[videoId]/transcoded/video/360/video.mp4,stream=video,output=.temp/[videoId]/packed/video/360/video.mp4" \
 *   "in=.temp/[videoId]/transcoded/video/480/video.mp4,stream=video,output=.temp/[videoId]/packed/video/480/video.mp4" \
 *   "in=.temp/[videoId]/transcoded/video/720/video.mp4,stream=video,output=.temp/[videoId]/packed/video/720/video.mp4" \
 *   "in=.temp/[videoId]/transcoded/video/1080/video.mp4,stream=video,output=.temp/[videoId]/packed/video/1080/video.mp4" \
 *   "in=.temp/[videoId]/transcoded/audio/audio.mp4,stream=audio,output=.temp/[videoId]/packed/audio/audio.mp4" \
 *   --mpd_output .temp/[videoId]/packed/dash/manifest.mpd \
 *   --hls_master_playlist_output .temp/[videoId]/packed/hls/master.m3u8
 *
 * Generated streaming formats:
 *
 * - MPEG-DASH  -> dash/manifest.mpd
 * - HLS        -> hls/master.m3u8
 */

type Resolution = 144 | 360 | 480 | 720 | 1080;

@Injectable()
export class ShakaPackagerService {
  constructor(private readonly pino: PinoLogger) {}

  private runPackagerArgs(args: string[], outputDir: string): Promise<void> {
    return new Promise((resolve, reject) => {
      const packager = spawn('packager', args, {
        cwd: outputDir,
        env: {
          ...process.env,
          TMPDIR: outputDir,
        },
      });

      let stderrData = '';

      packager.stderr.on('data', (data: Buffer) => {
        stderrData += data.toString();
      });

      packager.on('error', (error) => {
        this.pino.error('ShakaPackager error', error);
        reject(error);
      });

      packager.on('close', (code) => {
        if (code === 0) {
          resolve();
          return;
        }

        this.pino.error(
          `Shaka Packager exited with code ${code}: ${stderrData}`,
        );
        reject(
          new Error(`Shaka Packager exited with code ${code}: ${stderrData}`),
        );
      });
    });
  }

  private async prepareDirectories(outputDirectory: string): Promise<void> {
    await mkdir(outputDirectory, { recursive: true });
  }

  private videoCommand(inputDirectory: string, resolution: Resolution): string {
    const input = path.join(
      inputDirectory,
      'video',
      String(resolution),
      'video.mp4',
    );
    const output = `v_${resolution}p.mp4`;
    const playlist = `hls_${resolution}p.m3u8`;

    return `in=${input},stream=video,output=${output},playlist_name=${playlist}`;
  }

  private audioCommand(inputDirectory: string): string {
    const input = path.join(inputDirectory, 'audio', 'audio.mp4');
    const output = 'a_audio.mp4';
    const playlist = 'hls_audio.m3u8';

    return `in=${input},stream=audio,output=${output},playlist_name=${playlist}`;
  }

  private mpegDashCommand(): string[] {
    return ['--mpd_output', 'manifest.mpd', '--generate_static_live_mpd'];
  }

  private hlsCommand(): string[] {
    return [
      '--hls_master_playlist_output',
      'master.m3u8',
      '--hls_playlist_type',
      'VOD',
    ];
  }

  private buildArgs(
    inputDirectory: string,
    resolutions: Resolution[],
  ): string[] {
    return [
      ...resolutions.map((resolution) =>
        this.videoCommand(inputDirectory, resolution),
      ),
      this.audioCommand(inputDirectory),
      ...this.mpegDashCommand(),
      ...this.hlsCommand(),
    ];
  }

  async pack(params: { inputDirectory: string; outputDirectory: string }) {
    const { inputDirectory, outputDirectory } = params;

    await this.prepareDirectories(outputDirectory);

    const execute = (resolutions: Resolution[]) =>
      this.runPackagerArgs(
        this.buildArgs(inputDirectory, resolutions),
        outputDirectory,
      );

    return {
      toMax144: () => execute([144]),
      toMax360: () => execute([144, 360]),
      toMax480: () => execute([144, 360, 480]),
      toMax720: () => execute([144, 360, 480, 720]),
      toMax1080: () => execute([144, 360, 480, 720, 1080]),
    };
  }
}
